insert into volumes (id, title_ml) values (4, 'വാല്യം 4') on conflict (id) do nothing;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (4, 1, 'ആമുഖമായി', '31', '32');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'അസ്സിഹാഹുസ്സിത്തയുടെ നാലാം വാല്യം സമൂഹത്തിനു മുൻപിൽ അവതരിപ്പിക്കാൻ കഴിഞ്ഞതിൽ അളവറ്റ് സന്തോഷിക്കുകയും അല്ലാഹുവിനെ സ്തുതിക്കുകയും ചെയ്യുന്നു. ഇരുപത്തിയഞ്ച് കൊല്ലം മുമ്പാണ് ഈ ശ്രമം ആരംഭിച്ചത്. പൂർത്തിയാക്കാൻ സാധിക്കുമെന്ന് കരുതിയല്ല ഈ ശ്രമം ആരംഭിച്ചത്.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'ഖുർആനും ഹദീസും ഇസ്ലാമിക ജീവിതത്തിന്റെ രണ്ട് അടിസ്ഥാനങ്ങളാണ് എന്ന് മനസ്സിലാക്കിയപ്പോൾ അവയെക്കുറിച്ച് പഠിക്കാനാരംഭിച്ചു. ഖുർആൻ പരിഭാഷകൾ ലഭ്യമായിരുന്നു. എന്നാൽ ഹദീസ് ഗ്രന്ഥങ്ങളും പരിഭാഷകളും അന്ന് ലഭ്യമായിരുന്നില്ല. ഒരു മുസ്ലിം (അല്ലാഹുവിനെ അനുസരിക്കുന്നവൻ) എന്ന നിലക്ക് നബി(സ) പറഞ്ഞതും പ്രവർത്തിച്ചതും അറിഞ്ഞിരിക്കേണ്ടതുണ്ട്, അവ ജീവിതത്തിൽ പകർത്തേണ്ടതുണ്ട് എന്ന ബോധം ഉള്ളിലുണ്ടായിരുന്നു. പല വിഷയങ്ങളെക്കുറിച്ചും ഖുർആൻ എന്തു പറയുന്നുവെന്ന് കണ്ടുപിടിക്കുക എളുപ്പമായിരുന്നു. എന്നാൽ ഹദീസുകൾ എന്ത് പറയുന്നു എന്ന് കണ്ടുപിടിക്കുക എളുപ്പമായിരുന്നില്ല. പല വിഷയങ്ങളെക്കുറിച്ചും നബി(സ) എന്താണ് പറഞ്ഞത് എന്ന് പല പണ്ഡിതന്മാരോടും ചോദിക്കും. അവർ, നോക്കിപ്പറഞ്ഞുതരാം എന്നു പറയും. രണ്ടോ മൂന്നോ മാസം കഴിഞ്ഞു ചോദിച്ചാലും അതേ മറുപടിയായിരിക്കും ലഭിക്കുക. പിന്നീടാണ്, അവർക്കും ഇത് എളുപ്പത്തിൽ ചെയ്യാൻ കഴിയുമായിരുന്നില്ല എന്ന് മനസ്സിലായത്. അസ്സിഹാഹുസ്സിത്ത എന്ന ആറു ഗ്രന്ഥങ്ങൾ നാൽപ്പതിലധികം വാല്യങ്ങളിലായിട്ടാണ് കിടക്കുന്നത്. പലതും ആവർത്തനമാണ്. അതുകൊണ്ട് ഒരു വിഷയത്തെക്കുറിച്ചുള്ള ഹദീസുകൾ തേടിപ്പിടിക്കുക എളുപ്പമല്ല. ആയിരത്തി നാനൂറ് വർഷങ്ങൾക്കു മുമ്പുള്ള പദപ്രയോഗങ്ങളായതുകൊണ്ട് പല വാക്കുകളുടെയും അർത്ഥം മനസ്സിലാക്കാൻ പ്രയാസമായി. അന്ന് ബുഖാരിയും മുസ്ലിമും മാത്രമേ ഗ്രന്ഥരൂപത്തിൽ പ്രചാരത്തിലുണ്ടായിരുന്നുള്ളൂ. വ്യക്തിപരമായ ഒരാവശ്യം എന്ന നിലക്ക് ഹദീസ്പഠനം ആരംഭിച്ചു. ആറ് കിത്താബുകളും ശേഖരിക്കാൻതന്നെ ഒരു വർഷമെടുത്തു. ബോംബെയിൽനിന്നാണ് അവ ലഭിച്ചത്.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'പിന്നീട്, ഹദീസുകളിലെ ആവർത്തനം എങ്ങനെ ഒഴിവാക്കാം എന്ന് അഞ്ചുകൊല്ലം റിസേർച്ച് നടത്തി. പല രൂപത്തിലും ശ്രമം നടത്തിക്കൊണ്ടിരുന്നു. കമ്പ്യൂട്ടർ ഉപയോഗിച്ച് ശ്രമം നടത്തിയപ്പോൾ അതിൽ, പല പാകപ്പിഴവുകളും സംഭവിക്കുന്നതായി അനുഭവപ്പെട്ടു. അവസാനം അല്ലാഹുവിന്റെ അനുഗ്രഹം കൊണ്ട് കമ്പ്യൂട്ടറിന്റെ സഹായമില്ലാതെത്തന്നെ ഒരു രീതി രൂപപ്പെട്ടുവന്നു. അൽഹംദുലില്ലാഹ്... പിന്നീട് തർജ്ജുമ ചെയ്യുകയെന്ന ഒരു ഭാരിച്ച ജോലിയാണുണ്ടായിരുന്നത്. അതും പലരുടെയും സഹായംകൊണ്ട് നിർവ്വഹിക്കാൻ സാധിച്ചു.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'അസ്സിഹാഹുസ്സിത്തയിലെ എല്ലാ ഹദീസ് ഗ്രന്ഥങ്ങളിലുമുള്ള എല്ലാ ഹദീസുകളും ഈ സമാഹാരത്തിൽ ഉൾപ്പെടുത്താൻ ശ്രമിച്ചിട്ടുണ്ട്. അതിൽ ഒന്നും കൂട്ടുകയോ വിട്ടുകളയുകയോ ചെയ്തിട്ടില്ല.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'നബി(സ) പറഞ്ഞതും പ്രവർത്തിച്ചതും എല്ലാ മുസ്ലിംകളും അറിയുകയും ജീവിതത്തിൽ പകർത്തുകയും ചെയ്യേണ്ടതുണ്ട്. അതുകൊണ്ട് ഈ ഗ്രന്ഥം എല്ലാ വീടുകളിലും എല്ലാ വിദ്യാലയങ്ങളിലും എല്ലാ പള്ളികളിലും എത്തിക്കണമെന്നാഗ്രഹിക്കുന്നു. ഇതൊരു സ്വാലിഹായ അമലായിക്കണ്ടുകൊണ്ട് ഈ സംരംഭത്തിൽ സഹകരിക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഇത്, ഇത്തരത്തിലുള്ള ഒരാദ്യ സംരംഭമാണ്. അറബിഭാഷയിലും ഇതുപോലെ ഒരു സമാഹാരം ഉള്ളതായി ശ്രദ്ധയിൽ പെട്ടിട്ടില്ല. ഹദീസുകളുടെ എഡിറ്റിങ്ങിലും പരിഭാഷയിലും എന്തെങ്കിലും തകരാറുകൾ സംഭവിച്ചിട്ടുണ്ടെങ്കിൽ അത് ശ്രദ്ധയിൽപെടുത്തണമെന്നഭ്യർത്ഥിക്കുന്നു. ഗ്രന്ഥത്തിന്റെ വാല്യം, പേജ്, ക്രമം എന്നിവ എങ്ങനെ മെച്ചപ്പെടുത്താം എന്ന് എഴുതി അറിയിക്കുന്നത് കൂടുതൽ സഹായകമാവും. ഇനി ഇവ പ്രസിദ്ധീകരിക്കുമ്പോൾ അവയിൽ വേണ്ട തിരുത്തലുകൾ വരുത്താമല്ലോ.', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'ഈ ഗ്രന്ഥസമാഹാരത്തെക്കുറിച്ച് നിങ്ങളുടെ സുഹൃത്തുക്കളെയും ബന്ധുക്കളെയും അറിയിക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു. ഈ ഗ്രന്ഥങ്ങൾ ജനങ്ങൾക്ക് എത്തിക്കുമ്പോൾ നമ്മുടെ സമൂഹത്തിൽ തീർച്ചയായും ചില നല്ല ഫലങ്ങൾ ഉണ്ടാകുമെന്ന് പ്രതീക്ഷിക്കുന്നു. സാധാരണ ജനങ്ങൾക്ക് ഇപ്പോൾ എന്താണ് മതം, എന്താണ് മതമല്ലാത്തത് എന്ന് തിരിച്ചറിയാനുള്ള സാഹചര്യങ്ങളില്ല. പലരും നാട്ടുനടപ്പുകൾ മതമായി തെറ്റിദ്ധരിക്കുന്നു. ഈ അവസ്ഥ മാറണമെങ്കിൽ ഖുർആനും ഹദീസുകളും സാധാരണ', null, '31' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'ജനങ്ങളിലേക്ക് എത്തേണ്ടതുണ്ട്.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ഖുർആനും ഹദീസും സാധാരണ ജനങ്ങളിലേക്കെത്തിയാൽ അപകടങ്ങളുണ്ടാകുമെന്ന് ആത്മാർത്ഥമായി വിശ്വസിക്കുന്ന ചിലരുണ്ട്. അല്ലാഹുവിന്റെ ദീൻ അവൻ സംരക്ഷിക്കും എന്ന വസ്തുത അവർ തൽക്കാലം മറക്കുകയാണ്. റസൂൽ(സ) നിങ്ങൾക്ക് നൽകിയതെന്തോ അത് നിങ്ങൾ സ്വീകരിക്കുക. ഏതൊന്നിൽനിന്ന് നിങ്ങളെ വിലക്കിയോ അത് നിങ്ങൾ വെടിയുകയും ചെയ്യുക എന്ന അല്ലാഹുവിന്റെ നിർദ്ദേശം നമുക്ക് ജീവിതത്തിൽ പകർത്താൻ ശ്രമിക്കാം. അല്ലാഹു അനുഗ്രഹിക്കട്ടെ.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച എല്ലാവർക്കും അല്ലാഹു മതിയായ പ്രതിഫലം നൽകുമാറാകട്ടെ. ആദ്യകാലത്ത് ഈ സംരംഭത്തിന് എല്ലാവിധ പ്രോൽസാഹനവും നൽകിയ വൈലത്തൂർ അബ്ദുർറഹ്മാൻ സാഹിബിനെ (അൽഅമാൻ ബുക്ക്സ്റ്റാൾ) ഇവിടെ സ്മരിക്കുന്നു.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'മുൻവാല്യങ്ങൾക്കു പുറമെ ഹദീസ് വിജ്ഞാനകോശം മൂന്നാം വാല്യത്തിന്റെ ട്രാൻസ്ലേഷൻ, ടൈപിങ്, സെറ്റിങ്, എഡിറ്റിങ് തുടങ്ങിയവക്ക് ആദ്യാവസാനം സഹകരിച്ച പി.വി. ഉസ്മാൻ മഹ്ബൂബി വേങ്ങൂർ, എം.പി. മുഹമ്മദ് മൻസൂർ മഹ്ബൂബി ചാപ്പനങ്ങാടി, കെ.പി. ഖുബൈബ് മഹ്ബൂബി മാരിയാട്, എന്നിവർക്കും ഗ്രന്ഥം എഡിറ്റുചെയ്തു തന്ന അബ്ദുർറഹ്മാൻ മൗലവി പാണ്ടിക്കാടിനും പ്രത്യേകം കൃതജ്ഞത രേഖപ്പെടുത്തുന്നതോടൊപ്പം അവർക്ക് അല്ലാഹു ഉത്തമ പ്രതിഫലം നൽകട്ടെ എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'പ്രൊഫ: വി. മുഹമ്മദ് സാഹിബ്, എ. അബ്ദുസ്സലാം സാഹിബ്, ഡോ: അഹ്മദ് ഇസ്മാഈൽ ലബ്ബ, ഡോ: കെ മുഹമ്മദ് ബഷീർ, മുഹമ്മദ് മുജീബ് കാളിയാർ, മുഹമ്മദ് ശരീഫ് വി.പി, ഇ.എം ശരീഫ് മുതുതല, എം.കെ ഹസ്സൻ കോട്ടുമല, വി.എ.എം ഇസ്ഹാഖ് നദ്വി, അബൂബക്കർ പി.കെ, ഉമർ കെ.പി, ഇബ്രാഹീം നദ്വി, എൻ.കെ, ഹുസൈൻ ഷംസുദ്ദീൻ വെളിയംകോട്, അമാനുല്ല എ.കെ, മുഹമ്മദ് അഷ്റഫ് മൗലവി, പ്രൊഫ: മുഹമ്മദ് കുട്ടശ്ശേരി, ഫാറൂഖ് അബ്ദുല്ല നാദാപുരം, ഇ. അബ്ദുൽ ലത്തീഫ്, എം.പി മുഹമ്മദ് ഫൈസൽ അഹ്സനി, അബ്ദുൽ ഖാദർ അഹ്സനി, ഹാരിസ് എം. ഹുദവി, മുഹമ്മദ് അലി ഹുദവി, അൻവർ എ.പി, ശുക്കൂർ.ടി മേലണ്ണം, കബീർ അഞ്ചച്ചവിടി, ഇസ്മാഈൽ എടക്കുളം, റഫീഖ് കെ മമ്പറം, അബ്ദുൽ മജീദ് എൻ.കെ, ഉമൈർ സി.കെ, എം.എ. ആരിഫ, ശുക്കൂർ വള്ളിക്കുന്ന്, സഊദ് കൊട്ടപ്പുറം, ശഫീഖ് സി.പി, റാഷിദ് സി.കെ, മൈമൂന സി.കെ, ആരിഫ പി.പി, സൽമ, വി.എം. കൂട്ടി മൗലവി, അബൂബക്കർ പോരൂർ, യൂനുസ്.കെ പേങ്ങാട്, ശഫീഖ് മഹ്ബൂബി എടയാറ്റൂർ, അശ്റഫ് മഹ്ബൂബി വെളിമുക്ക്, സുബൈർ മഹ്ബൂബി വേങ്ങര, റാഫി മഹ്ബൂബി ഇരിങ്ങാട്ടിരി, സ്വാലിഹ് മഹ്ബൂബി കുമരനല്ലൂർ, ഹിദായത്തുല്ല മഹ്ബൂബി മുതുപറമ്പ്, അബ്ദുറഹീം മഹ്ബൂബി ചങ്കുവെട്ടി, അബ്ദുൽഅസീസ് മഹ്ബൂബി പുലിക്കോട് എന്നിവർ ഈ സംരഭത്തിൽ സഹകരിച്ചവരാണ്. ഈ കൃതി തയ്യാറാക്കുന്നതിൽ സഹകരിച്ച മറ്റു വല്ലവരുടെയും പേരുകൾ വിട്ടുപോയിട്ടുണ്ടെങ്കിൽ ക്ഷമിക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'ഈ ഗ്രന്ഥരചനയുടെ എല്ലാ ഘട്ടങ്ങളിലും താൽപര്യമെടുക്കുകയും പങ്കുവഹിക്കുകയും ചെയ്ത എന്റെ സഹധർമ്മിണി പ്രൊഫ: ഹബീബയെ ഈ സന്ദർഭത്തിൽ അനുസ്മരിക്കുന്നു. വെളിയംകോട് ഉമർ മൗലവിയുടെ മകളായ അവളെ അവളുടെ ഉപ്പ അറബി ഭാഷ നന്നായി പഠിപ്പിച്ചത് ഈ ഗ്രന്ഥരചനക്ക് സഹായകമായി. എന്റെ എല്ലാ ഇസ്ലാമിക പ്രവർത്തനങ്ങൾക്കും കലവറയില്ലാത്ത പ്രോത്സാഹനമാണ് അവർ നൽകിക്കൊണ്ടിരിക്കുന്നത്. അവൾക്കും അവളുടെ പിതാവിനും അല്ലാഹു അനുഗ്രഹം നൽകുമാറാകട്ടെ.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'ഒന്നാം വാല്യത്തിന്റെ ആമുഖമായി പറഞ്ഞ കാര്യങ്ങൾ നാലാം വാല്യത്തിൽനിന്ന് ഒഴിവാക്കുകയാണ്. വായിച്ചു തുടങ്ങുന്നവർ ഒന്നാം വാല്യത്തിലെ ആദ്യഭാഗങ്ങൾകൂടി വായക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു.', null, '32' from articles where volume_id=4 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'ഡോ: മുസ്തഫാ കമാൽ പാഷ', null, '32' from articles where volume_id=4 and section_no=1;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (4, 2, 'ഹദീസിന്റെ പ്രാധാന്യം', '33', '34');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'ഇസ്ലാം ഒരു ജീവിത രീതിയാണ്. അത് പ്രവർത്തനമാണ്. അതൊരു തത്വചിന്തയല്ല. അതുകൊണ്ടുതന്നെ, ദൈനംദിന ജീവിതത്തിൽ ഇസ്ലാമിക സിദ്ധാന്തങ്ങൾ പ്രയോഗവത്കരിക്കേണ്ടതുണ്ട്. മുഹമ്മദ് നബി(സ) ഒരാത്മീയ ഗുരു മാത്രമായിരുന്നില്ല. നോമ്പും നമസ്ക്കാരവും സക്കാത്തും ഹജ്ജുമൊക്കെ മുഹമ്മദ് നബി(സ)ക്ക് പ്രയോഗവത്കരിച്ചു കാണിക്കേണ്ടതുണ്ടായിരുന്നു. അനുയായികളെ അവ പഠിപ്പിക്കേണ്ടതുണ്ടായിരുന്നു. മാത്രമല്ല ഖുർആൻ പരിചയപ്പെടുത്തുന്നത് നബി(സ) ന്യായാധിപൻ കൂടിയാണെന്നാണ്. അതുകൊണ്ടുതന്നെ നബി(സ)ക്ക് ഭരണകർത്താവിന്റെ ഭാഗം കൂടി പ്രയോഗവത്കരിച്ചു കാണിക്കേണ്ടതുണ്ടായിരുന്നു. നബി(സ) ഒരു രാഷ്ട്രം സ്ഥാപിക്കുകയും അതിൽ അല്ലാഹുവിന്റെ നിയമങ്ങൾ നടപ്പാക്കി കാണിക്കുകയും ചെയ്തു. ദൈവിക മാർഗ്ഗനിർദ്ദേശങ്ങൾ മതരംഗത്തും സാമൂഹിക രംഗത്തും രാഷ്ട്രീയരംഗത്തും കുടുംബരംഗത്തും എങ്ങനെ പ്രയോഗവത്കരിക്കണം എന്ന് നബി(സ) പ്രവർത്തിച്ചു കാണിച്ചു തന്നു. ഇസ്ലാമിൽ വിശ്വാസത്തിന് മാത്രമല്ല പ്രാധാന്യം. അല്ലാഹു പറയുന്നു: ''വിശ്വസിക്കുകയും സൽകർമ്മം പ്രവർത്തിക്കുകയും സത്യംകൊണ്ടും സഹനം കൊണ്ടും പരസ്പരം ഉപദേശിക്കുകയും ചെയ്യാത്തവരൊക്കെ നാശത്തിലാണ്, നഷ്ടത്തിലാണ്'' (സൂറത്തുൽ അസ്വർ). കാലത്തെ സാക്ഷി നിർത്തിക്കൊണ്ടാണ് അഥവാ ചരിത്രത്തെ സാക്ഷി നിർത്തിക്കൊണ്ടാണ് ഖുർആൻ ഇങ്ങനെ പറയുന്നത്. നബി(സ) കാണിച്ചു തന്ന ഖുർആനിന്റെ ഈ പ്രയോഗവത്കരണത്തിന് വളരെയധികം പ്രാധാന്യമുണ്ട്. നബിചര്യയെ മനസ്സിലാക്കാതെ, അവ പഠിക്കാതെ, അവ പ്രയോഗവത്കരിക്കാതെ ഇസ്ലാം പൂർണ്ണമാവില്ല. ആയിശ(റ)യോട് നബി(സ)യുടെ ജീവിതം എങ്ങിനെയായിരുന്നു എന്നു ചോദിച്ചപ്പോൾ അതിനുള്ള മറുപടിയായി ആയിശ(റ) പറഞ്ഞത് അത് ഖുർആനായിരുന്നുവെന്നാണ്. നബി(സ) എങ്ങനെയാണ് ഖുർആൻ പ്രയോഗവത്കരിച്ചത് എന്നറിയണമെങ്കിൽ നബി(സ) പറഞ്ഞതും ചെയ്തതുമായ കാര്യങ്ങൾ നാം മനസ്സിലാക്കേണ്ടതുണ്ട്. അത് സാധിക്കണമെങ്കിൽ നാം ഹദീസുകൾ പഠിക്കുകയും പ്രയോഗവത്കരിക്കുകയും ചെയ്യേണ്ടതുണ്ട്.', null, '33' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'ഖുർആൻ ഇരുപത്തിമൂന്ന് വർഷങ്ങളിലായി പല സന്ദർഭങ്ങളിലാണ് അവതരിക്കപ്പെട്ടത്. ഖുർആനിലെ വാക്യങ്ങളുടെ അവതരണ പശ്ചാതലം കൂടി മനസ്സിലാക്കിയാലേ ഖുർആൻ വേണ്ടവിധത്തിൽ മനസ്സിലാക്കാൻ കഴിയൂ. ഇത് നമുക്ക് ലഭിക്കുന്നത് ഹദീസുകളിൽ നിന്നാണ്. മറ്റു വാക്കുകളിൽ പറഞ്ഞാൽ ഖുർആൻ മനസ്സിലാക്കണമെങ്കിൽ ഹദീസ് പഠനം അനിവാര്യമാണ്. ഹദീസിന്റെ അഭാവത്തിൽ അവശേഷിക്കുന്നത് എന്തായിരിക്കും? ഖുർആൻ തന്നെ നേരെ ചൊവ്വെ മനസ്സിലാക്കാൻ നമുക്ക് പ്രയാസമാവും. കാരണം പല ഖുർആൻ വചനങ്ങളുടെയും അവതരണ പശ്ചാത്തലംകൂടി മനസ്സിലാവുമ്പഴേ ഖുർആനിക വാക്യങ്ങളുടെ അർത്ഥവും വ്യാപ്തിയും നമുക്കു മനസ്സിലാക്കാൻ കഴിയുകയുള്ളൂ.', null, '33' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'ഹദീസുകളുടെ അഭാവത്തിൽ മുസ്ലിം സമൂഹത്തിന്റെ സാംസ്ക്കാരികമായ വ്യക്തിത്വം ഇല്ലാതാവുന്നു. സമൂഹത്തിലെ പെരുമാറ്റ മര്യാദകളും വസ്ത്രധാരണാരീതികളും ദിനചര്യകളിലുള്ള പ്രത്യേകതകളുമൊക്കെ നമുക്കു ലഭിക്കുന്നത് നബിചര്യയിൽ നിന്നാണ്. ഹദീസുകൾ നിഷേധിക്കുന്നതോടെ മുസ്ലിം സമൂഹത്തിന്റെ വ്യക്തിത്വവും വ്യതിരിക്തതയും നഷ്ടമാവുകയാണ് ചെയ്യുക.', null, '33' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ചൈനയിലെ മുസ്ലിമായാലും മൊറോക്കോയിലെ മുസ്ലിമായാലും ഇംഗ്ലണ്ടിലെ മുസ്ലിമായാലും അമേരിക്കയിലെ മുസ്ലിമായാലും അവരെല്ലാം മുസ്ലിം സമൂഹത്തിന്റെ ഭാഗമാണെന്ന് ഏതൊരു വിദേശിക്കും മനസ്സിലാക്കിക്കൊടുക്കുന്ന ചില പ്രത്യേകതകളുണ്ട്. അവരുടെ ഭാഷയും വേഷവും വ്യത്യസ്തമായിരിക്കാം. എങ്കിലും അവരെ പരസ്പരം ഏകീകരിക്കുന്ന കുറെ ഘടകങ്ങളുണ്ടാവും. ലോകത്തുള്ള മുസ്ലിംങ്ങളെല്ലാം അഞ്ചുനേരം നമസ്കരിക്കും. പള്ളികളിൽ അഞ്ചുനേരത്തെ പ്രാർത്ഥനക്കും വെള്ളിയാഴ്ച്ചകളിൽ ജുമുഅക്കും ഒത്തുചേരുന്നു. പുരുഷന്മാർ താടി വളർത്തുന്നു. സ്ത്രീകൾ തലമറക്കുന്നു. പരസ്പരം കാണുമ്പോൾ സലാം പറയുന്നു. അങ്ങനെ പലതും കാണാം.', null, '33' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'അല്ലാഹു ഖുർആനിൽ പലയിടത്തും നബി(സ)യെ അനുസരിക്കണമെന്നും അദ്ദേഹത്തിൽ ഉത്തമമാതൃകയുണ്ടെന്നും അതനുസരിച്ച് ജീവിക്കണമെന്നും നിർദ്ദേശിക്കുന്നുണ്ട്. ചില ഉദാഹരണങ്ങൾ കാണുക:', null, '33' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', '''അല്ലാഹുവിനെയും അവന്റെ ദൂതനെയും അനുസരിക്കുക.'' (ഖു. 5: 92)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', '''ദൈവദൂതനെ ആരനുസരിച്ചുവോ അവൻ തീർച്ചയായും അല്ലാഹുവിനെ അനുസരിച്ചു.'' (ഖു. 4: 80)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', '''നിശ്ചയമായും അല്ലാഹുവിന്റെ ദൂതനിൽ ഉത്തമമായ മാതൃകയുണ്ട്. അതായത്, അല്ലാഹുവിലും അന്ത്യനാളിലും പ്രതീക്ഷപുലർത്തുകയും അല്ലാഹുവിനെ ധാരാളമായി സ്മരിക്കുകയും ചെയ്യുന്നവർക്ക്.'' (ഖു. 33: 21)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', '''സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിനെയും അവന്റെ ദൂതനെയും അനുസരിക്കുവിൻ, നിങ്ങളിൽ നിന്നുള്ള കൈകാര്യ കർത്താക്കളെയും അനുസരിക്കുക. ഏതെങ്കിലും കാര്യത്തിൽ നിങ്ങൾക്കിടയിൽ ഭിന്നിപ്പുണ്ടാവുകയാണെങ്കിൽ നിങ്ങളത് അല്ലാഹുവിലേക്കും ദൂതനിലേക്കും മടക്കുക. നിങ്ങൾ അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ (അതാണ് ചെയ്യേണ്ടത്), അതാണ് ഏറ്റവും ഉത്തമവും ഏറ്റവും നല്ല പര്യവസാനമുള്ളതും.'' (ഖു. 4: 59)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', '''അല്ലാഹുവിന്റെ കൽപ്പനപ്രകാരം അനുസരിക്കപ്പെടാൻ വേണ്ടിയല്ലാതെ ഒരൊറ്റ പ്രവാചകനെയും നാം അയച്ചിട്ടില്ല. തങ്ങളോടു തന്നെ അക്രമം പ്രവർത്തിച്ചപ്പോൾ അവർ അങ്ങയെ സമീപിക്കുകയും അല്ലാഹുവിനോട് മാപ്പിരക്കുകയും അവർക്ക് വേണ്ടി റസൂലും പാപമോചനം തേടുകയും ചെയ്തിരുന്നെങ്കിൽ അല്ലാഹുവിനെ ഏറെ പശ്ചാത്താപം സ്വീകരിക്കുന്നവനും കരുണാനിധിയുമായി അവർ കണ്ടെത്തുക തന്നെ ചെയ്യുമായിരുന്നു.'' (ഖു. 4: 64 – 65)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', '''അല്ല, നിന്റെ നാഥനെത്തന്നെയാണ് സത്യം, അവർക്കിടയിലുള്ള തർക്കങ്ങളിൽ അവർ അങ്ങയെ വിധികർത്താവായി സ്വീകരിക്കുകയും എന്നിട്ട് അങ്ങ് നൽകുന്ന വിധിതീർപ്പുകളിൽ പിന്നീട് അവരുടെ മനസ്സുകളിൽ ഒരു പ്രയാസം തോന്നാതിരിക്കുകയും അത് പൂർണ്ണമായും സമ്മതിച്ച് അനുസരിക്കുകയും ചെയ്യുന്നത് വരെ അവർ വിശ്വാസികളാവുകയില്ല.'' (ഖു. 4: 65)', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'ഇസ്ലാമിക കർമ്മാനുഷ്ഠാനങ്ങളായ നമസ്കാരം, നോമ്പ്, സകാത്ത്, ഹജ്ജ് തുടങ്ങിയവയുടെ പ്രായോഗിക വിശദാംശങ്ങൾ നമുക്ക് ലഭിക്കുന്നത് നബി(സ)യുടെ ചര്യയിൽ നിന്നാണ്. ഹദീസുകളെ ഒഴിവാക്കിയാൽ നമുക്ക് ഈ കർമ്മാനുഷ്ഠാനങ്ങൾ യഥാവിധി നിർവഹിക്കാനാകില്ല. ഇസ്ലാമിക ജീവിതത്തിനു ഹദീസുകൾ അനിവാര്യമാണെന്ന് ഇതു കാണിക്കുന്നു.', null, '34' from articles where volume_id=4 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'ഖുർആൻ അല്ലാഹുവിൽ നിന്ന് മനുഷ്യനുള്ള വാക്യരൂപത്തിലുള്ള നിർദ്ദേശങ്ങളാണ്. ഒരു മനുഷ്യൻ അവക്കനുസരിച്ച് എങ്ങനെ ജീവിക്കണമെന്നുള്ള സന്ദേശമാണു നബിചര്യയിലൂടെ നമുക്ക് ലഭിക്കുന്നത്. ഖുർആനിക നിർദ്ദേശങ്ങൾക്കനുസരിച്ച് ഒരു മനുഷ്യൻ എങ്ങനെയാണ് ജീവിക്കേണ്ടത് എന്ന് കാണിച്ചുതരികയാണ് (Demonstrate ചെയ്യുകയാണ്) നബി(സ) ചെയ്തത്. അല്ലാഹു ഒരു ഗ്രന്ഥം നൽകുക മാത്രമല്ല അതനുസരിച്ച് എങ്ങനെ ജീവിക്കാമെന്ന് ജനങ്ങളെ പഠിപ്പിക്കാൻ ഒരു പ്രവാചകനെ അയക്കുക കൂടി ചെയ്തു. അതൊരാവശ്യമാണെന്ന് കണ്ടതുകൊണ്ടായിരിക്കണം അല്ലാഹു അങ്ങനെ ചെയ്തത്. അല്ലെങ്കിൽ ഗ്രന്ഥം മാത്രം നൽകിയാൽ മതിയായിരുന്നല്ലോ? ദൈവദൂതനെ അനുസരിക്കണമെന്നും തിരുമേനി(സ)യിൽ ഉത്തമ മാതൃകയുണ്ടെന്നും അവിടുത്തെ പിൻപറ്റണമെന്നും അല്ലാഹു നിർദ്ദേശിക്കുമായിരുന്നില്ലല്ലോ?', null, '34' from articles where volume_id=4 and section_no=2;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (4, 3, 'ഓറിയന്റലിസ്റ്റുകളും അവരുടെ ജൽപ്പനങ്ങളും', '34', '37');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'പൗരസ്ത്യ ഭാഷയും സംസ്കാരവും പഠിക്കുകയും ഗവേഷണം നടത്തുകയും ചെയ്യുന്ന പണ്ഡിതന്മാർക്കാണ് ഓറിയന്റലിസ്റ്റുകൾ (പൗരസ്ത്യ പണ്ഡിതന്മാർ) എന്ന് പറയുന്നത്. ക്രിസ്താബ്ദം 11, 12 നൂറ്റാണ്ടുകളിൽ മുസ്ലിംകളും ക്രിസ്ത്യൻ യൂറോപ്പും തമ്മിൽ പതിനാറു യുദ്ധങ്ങൾ നടന്നു. അവയിലെല്ലാം ക്രിസ്ത്യാനികൾ തോറ്റു. നേർക്കുനേരെയുള്ള യുദ്ധത്തിൽ മുസ്ലിംകളോട് ജയിക്കാനാവില്ല എന്ന് യൂറോപ്പ്യൻമാർ മനസ്സിലാക്കി. മുസ്ലിംകളെ ഇസ്ലാമിൽ നിന്നകറ്റിയാലേ അവരെ തോൽപ്പിക്കാനാവൂ എന്നവർ മനസ്സിലാക്കി. പിന്നീടുള്ള കുരിശുയുദ്ധങ്ങൾ ആ വഴിക്കായിരുന്നു. അറബിഭാഷയും ഖുർആനും ഹദീസും ഇസ്ലാമിക ചരിത്രവും പഠിച്ച് അവയിലുള്ള മുസ്ലിംകളുടെ വിശ്വാസം എങ്ങനെ തകർക്കാം എന്നാണവർ ചിന്തിച്ചത്. അതിനുവേണ്ടി വലിയ ഫണ്ടുകൾ (ധനം) ശേഖരിച്ചു അവർ ബാങ്കുകളിൽ നിക്ഷേപിച്ചു.', null, '34' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'അതിൽ നിന്നു ലഭിക്കുന്ന പലിശ കൊണ്ട് അറബിഭാഷയെക്കുറിച്ചും ഇസ്ലാമികചരിത്രത്തെക്കുറിച്ചും പഠിക്കുന്ന പണ്ഡിതന്മാർക്ക് ശമ്പളം നൽകി. അവരുടെ ഗവേഷണപ്രബന്ധങ്ങളും പുസ്തകങ്ങളും പ്രസിദ്ധീകരിച്ചു കൊണ്ടിരിക്കുന്നു. അങ്ങനെ ഗവേഷണം നടത്താനുള്ള സ്ഥാപനങ്ങൾ ജർമ്മനിയിലും കാനഡയിലും യൂറോപ്യൻ രാജ്യങ്ങളിലും ഇന്നും പ്രവർത്തിക്കുന്നു. ഈ രൂപത്തിലുള്ള കുരിശുയുദ്ധങ്ങൾ ഇന്നും തുടരുന്നു. ഓറിയന്റലിസ്റ്റുകൾ യൂനിവേഴ്സ്റ്റികളിലെ അറബി ഡിപ്പാർട്ടുമെന്റുകളിലും ഇസ്ലാമിക് ഹിസ്റ്റി ഡിപ്പാർട്ടുമെന്റുകളിലും ഹിസ്റ്ററി ഡിപ്പാർട്ടുമെന്റുകളിലും പ്രവർത്തിച്ചുകൊണ്ടിരിക്കുന്നു. അവരുടെ കുരിശുയുദ്ധം നിരന്തരം തുടരുകയാണ്. അവരുടെ പ്രവർത്തനമേഖലയുടെ ഒരു ഭാഗമാണ് ഹദീസുകളെക്കുറിച്ചുള്ള പഠനങ്ങൾ. ഹദീസുകളിൽ സംശയം തോന്നിക്കുക, ഹദീസ് റിപ്പോർട്ടർമാരുടെ വിശ്വാസ്യത ചോദ്യം ചെയ്യുക, മുസ്ലിം സമൂഹത്തിൽ നിന്നുതന്നെ ഹദീസ് നിഷേധികളെ വാർത്തെടുക്കുക തുടങ്ങിയവ അവരുടെ കർമ്മമേഖലയാണ്. ഇതൊന്നും മനസ്സിലാക്കാതെ മുസ്ലിം സമൂഹത്തിലെ പലരും അവരുടെ കെണിയിലകപ്പെടാറുണ്ട്. പാശ്ചാത്യൻ യൂണിവേഴ്സിറ്റികളിലും അറബ്‌രാജ്യങ്ങളിൽ തന്നെ പ്രവർത്തിക്കുന്ന യൂണിവേഴ്സിറ്റികളിലും ഇത്തരം പണ്ഡിതന്മാർ കയറിക്കൂടുന്നു. അവിടെ പി.എച്ച്.ഡി ചെയ്യാനും മറ്റും എത്തുന്ന വിദ്യാർത്ഥികളെ അവർ മസ്തിഷ്കപ്രക്ഷാളനം (Brain Wash) നടത്തുന്നു. അറബിഭാഷയിലും ഹദീസുകളിലും അവർക്കുള്ള പാണ്ഡിത്യം കണ്ട് പല മുസ്ലിം വിദ്യാർത്ഥികളും അമ്പരക്കാറുണ്ട്. അവരുടെ ആരാധകരായി മാറാറുണ്ട്. അവർ പറയുന്നത് ശരിയല്ലേ എന്നു ചിന്തിക്കാറുണ്ട്. ഓറിയന്റലിസ്റ്റുകളുടെ നിഗൂഢ ലക്ഷ്യങ്ങളെക്കുറിച്ച് ആ വിദ്യാർത്ഥികൾ പലപ്പോഴും ബോധവാന്മാരായിരിക്കുകയില്ല. ഓറിയന്റലിസ്റ്റുകൾ സാധാരണ ഉന്നയിക്കാറുള്ള ചില വാദമുഖങ്ങൾ നമുക്കു പരിശോധിക്കാം.', null, '35' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'നബി(സ)യുടെ കാലത്ത് ഹദീസുകൾ എഴുതിവെക്കരുത് എന്ന ഒരു പൊതുനിർദ്ദേശം നൽകിയിരുന്നു. ഹദീസുകളും ഖുർആനിക വാക്യങ്ങളും കൂടിക്കലരരുത് എന്ന ലക്ഷ്യം വെച്ചുകൊണ്ടുള്ള ഒരു പൊതു നിർദ്ദേശം മാത്രമായിരുന്നു അത്. ജനങ്ങളെല്ലാം ഹദീസുകളും ഖുർആനും ഒന്നിച്ചെഴുതി വെച്ചാൽ ഉണ്ടായേക്കാവുന്ന ഒരു പ്രശ്നം ഒഴിവാക്കുക എന്നതായിരുന്നു ഹദീസുകൾ എല്ലാവരും എഴുതിവെക്കരുത് എന്ന് നബി(സ) നിർദ്ദേശിച്ചതിന്റെ ലക്ഷ്യം. അതു മനസ്സിലാക്കിക്കൊണ്ടുതന്നെ പല സ്വഹാബിമാരും ഹദീസുകൾ എഴുതിവെച്ചിരുന്നു. ഉദാഹരണമായി അംറുബ്നു ആസ്(റ), അബൂഹുറൈറ(റ), ഇബ്നുഅബ്ബാസ്(റ) എന്നിവർ ഹദീസുകൾ എഴുതിവെച്ചു. സക്കാത്തിന്റെ നിസാബിനെക്കുറിച്ചുള്ള കണക്ക് നബി(സ) എഴുതി സൂക്ഷിച്ചിരുന്നു. നബി(സ) പല ഗോത്രത്തലവന്മാർക്കും രാജാക്കന്മാർക്കും എഴുതിയ കത്തുകൾ നമുക്ക് ലഭിച്ചിട്ടുണ്ട്. നബി(സ)യുടെ കാലത്ത് എഴുത്ത് പ്രചാരത്തിലില്ലായിരുന്നുവെന്നും ഓറിയന്റലിസ്റ്റുകൾ പ്രചരിപ്പിക്കാറുണ്ട്. എന്നാൽ ഇത് ശരിയല്ല. നബി(സ)ക്കു മുമ്പുതന്നെ മുഅല്ലഖകൾ എന്നു പറയുന്ന മഹാകാവ്യങ്ങൾ എഴുതി കഅബയുടെ ചുവരുകളിൽ കെട്ടിത്തൂക്കിയിരുന്നു എന്നു നമുക്കറിയാം. ബദറിൽ തടവുകാരായി പിടിക്കപ്പെട്ട എഴുത്തും വായനയുമറിയുന്ന തടവുപുള്ളികളെ മോചിപ്പിക്കാനുള്ള മോചനദ്രവ്യമായി നിശ്ചയിച്ചത് ഓരോരുത്തരും പത്തു മുസ്ലിംകളെ എഴുത്തും വായനയും പഠിപ്പിക്കുക എന്നതായിരുന്നുവെന്നത് അക്ഷരാഭ്യാസത്തിനു നബി(സ) എത്രമാത്രം പ്രാധാന്യം കൽപ്പിച്ചിരുന്നുവെന്ന് സൂചിപ്പിക്കുന്നു. അല്ലാഹുവിൽ നിന്ന് നബി(സ) മുഖേനെ മനുഷ്യനു ലഭിച്ച ആദ്യത്തെ കൽപ്പന തന്നെ ഇഖ്റഅ് എന്നായിരുന്നല്ലോ. നബി(സ) മദീനയിലെത്തിയപ്പോൾ അവിടെയുള്ള ജൂതന്മാരും ക്രിസ്ത്യാനികളുമായി ഉടമ്പടികൾ ലിഖിതരൂപത്തിലുണ്ടാക്കി എന്നു നമുക്കറിയാം. അതുപോലെ മദീനയിൽ ഒരു ഇസ്ലാമിക രാഷ്ട്രം സ്ഥാപിച്ചപ്പോൾ ഒരു ഭരണഘടനക്ക് നബി(സ) രൂപം കൊടുത്തു. മദീനാ ചാർട്ടർ എന്ന പേരിൽ അത് ലിഖിതരൂപത്തിലുണ്ടായിരുന്നു. ഹുദൈബിയാ സന്ധി ലിഖിതരൂപത്തിലുണ്ടാക്കിയതും അതിൽ നബി(സ) ഒപ്പുവെച്ച സംഭവവും ചരിത്രത്തിലുള്ളതാണല്ലോ. ഉമറുബ്നുൽഖത്താബ്(റ)വിന്റെ ഇസ്ലാമാശ്ലേഷണത്തിന്റെ പശ്ചാത്തലം തന്നെ അദ്ദേഹത്തിന്റെ സഹോദരിയുടെ ലിഖിതരൂപത്തിലുള്ള ഖുർആനികാദ്ധ്യായത്തിന്റെ പാരായണം കേട്ടതും അതു വായിക്കാൻ ഉമർ(റ) ആഗ്രഹം പ്രകടിപ്പിച്ചതുമാണല്ലോ. ഇതുപോലെ നിരവധി സംഭവങ്ങൾ ചരിത്രത്തിലുണ്ടായിരിക്കെ, നബി(സ)യുടെ കാലത്ത് ജനങ്ങൾക്ക് എഴുത്തും വായനയും അറിയുമായിരുന്നില്ല, അവർ കാര്യങ്ങൾ എഴുതിവെക്കാറുണ്ടായിരുന്നില്ല എന്നൊക്കെ പറയുന്നത് ചരിത്രത്തെക്കുറിച്ച് അറിവില്ലാത്തവർ മാത്രമെ വിശ്വസിക്കൂ. നബി(സ) ഖുർആൻ എഴുതിവെക്കാൻ ചില സ്വഹാബിമാരോട് നിർദ്ദേശിച്ചു എന്നത് മറ്റുള്ളവർ ഖുർആൻ എഴുതിവെക്കാറില്ലായി', null, '35' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'രുന്നു എന്നർത്ഥമാക്കുന്നില്ല. പല സ്വഹാബിമാരും ഖുർആനും ഹദീസുമൊക്കെ എഴുതിവെക്കാറുണ്ടായിരുന്നു.', null, '36' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'അറബികൾ പൊതുവിൽ ഓർമ്മശക്തി വളരെ കൂടുതലുള്ളവരായിരുന്നു. ഓരോ. ഗോത്രത്തിന്റെയും പൂർവ്വപിതാക്കളുടെ പേരുകൾ ഓരോ ഗോത്രത്തിലുള്ളവരും മനപ്പാഠമാക്കി. മുഅല്ലഖ പോലുള്ള കവിതകൾ അവർ മനപ്പാഠമാക്കുകയും ചൊല്ലുകയും ചെയ്യും. കവിതക്ക് വളരെയധികം പ്രചാരമുള്ള ഒരു സമൂഹമായിരുന്നു അറബികളുടേത്. അവരിൽ പലരും കവിതകൾ രചിക്കുകയും ആലപിക്കുകയും ചെയ്തു. സാധാരണ ജനങ്ങളും കവിതകൾ ഓർമ്മിക്കുകയും പാടുകയും ചെയ്യുമായിരുന്നു. അവരുടെ ജീവിതരീതിയും അതിനെ പ്രോത്സാഹിപ്പിക്കുന്ന വിധത്തിലായിരുന്നു. കവിത ചൊല്ലുന്ന സദസ്സുകൾ അവർ സംഘടിപ്പിച്ചു. കച്ചവടക്കാരായ അവർ നിലാവുള്ള രാത്രികളിൽ യാത്ര ചെയ്യുമ്പോൾ കവിതകൾ ആലപിക്കും. ഓർമ്മശക്തിയെ സംബന്ധിച്ചിടത്തോളം Use it or lose it (ഉപയോഗിക്കുക അല്ലെങ്കിൽ നഷ്ടപ്പെടും) എന്നാണല്ലോ. ഓർമ്മശക്തി വർദ്ധിപ്പിക്കുന്ന തരത്തിലുള്ള അവരുടെ ജീവിതശൈലി ഓർമ്മശക്തി കൂടുതൽ കൂടുതൽ വർദ്ധിക്കാൻ കാരണമായി. ആ ജനതക്ക് ഖുർആനും ഹദീസും മനപ്പാഠമാക്കുക എന്നതും ഓർമ്മിക്കുക എന്നതും പ്രയാസമുള്ള കാര്യമായിരുന്നില്ല. യമാമ യുദ്ധത്തിൽ മരിച്ചവരുടെ കൂട്ടത്തിൽ 70 ഹാഫിളുകൾ (ഖുർആൻ മുഴുവൻ മനപ്പാഠമാക്കിയവർ) ഉണ്ടായിരുന്നു.', null, '36' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഹദീസിനെ നിഷേധിക്കുന്നവർ ഒരു ഉദാഹരണം മുന്നോട്ടുവെക്കാറുണ്ട്. പത്തുപേരെ വരിക്കുനിർത്തി ആദ്യത്തെ ആളുടെ ചെവിയിൽ എന്തോ പറഞ്ഞുകൊടുക്കുന്നു. അതയാൾ രണ്ടാമത്തെ ആളുടെ ചെവിയിൽ പറയുന്നു. രണ്ടാമത്തെ ആൾ മൂന്നാമത്തെയാളുടെ ചെവിയിൽ പറഞ്ഞുകൊടുക്കുന്നു. അങ്ങനെ പത്താമത്തെ ആളുടെ ചെവിയിലെത്തുമ്പോഴേക്കും ആദ്യത്തെ ആൾ പറഞ്ഞതിൽ നിന്നും വളരെ വ്യത്യസ്തമായ ഒരു കാര്യമായി അതു പുറത്തുവരുന്നു. ഇതുപോലെ ഹദീസുകളിലും മാറ്റം സംഭവിക്കില്ലേ? എന്നാണ് ഹദീസ് നിഷേധികൾ പറയുക. എന്നാൽ ഹദീസിന്റെ കാര്യവും ഈ ഉദാഹരണവും തമ്മിൽ താരതമ്യപ്പെടുത്താവതല്ല. ഒന്നാമത് ആധുനിക സമൂഹത്തിൽ ഓർമ്മശക്തി കുറഞ്ഞവരാണ് അധികവും. രണ്ടാമത് ഈ ഉദാഹരണത്തിൽ പങ്കെടുക്കുന്നവർ പലരും ഗൗരവത്തിലല്ല അതിൽ പങ്കെടുക്കുന്നത്. ഹദീസിന്റെ കാര്യം അങ്ങനെയല്ല. നബി(സ)യുടെ പേരിൽ ഒരാൾ കള്ളം പറഞ്ഞാൽ അയാളുടെ സ്ഥാനം നരകത്തിലാണെന്ന് വിശ്വസിക്കുന്നവരാണ് മുസ്ലിംകൾ. ഹദീസുകൾ പഠിക്കുന്നതും ഓർമ്മിക്കുന്നതും മറ്റൊരാൾക്ക് പറഞ്ഞുകൊടുക്കുന്നതും പുണ്യമായ ഒരു കർമ്മമായിട്ടാണ് മുസ്ലിംകൾ കണ്ടത്. അല്ലാഹുവിന്റെ മുമ്പിൽ ഉത്തരം പറയേണ്ടിവരുന്ന ഒരു ബാധ്യതയായി അവർ അതിനെ കാണുന്നു. അതുകൊണ്ടുതന്നെ, വളരെ ഗൗരവത്തോടും ശ്രദ്ധയോടും കൂടിയാണ് അവർ ഹദീസുകൾ മനപ്പാഠമാക്കിയതും റിപ്പോർട്ട് ചെയ്തതും. ഹദീസ് ശേഖരിക്കുന്നവർ വളരെയധികം പരിശോധന നടത്തിയാണ് ഹദീസുകൾ രേഖപ്പെടുത്തിയത്.', null, '36' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'നബി(സ)യുടെ അനുയായികൾ അവിടുത്തെ വളരെയധികം ആദരിക്കുകയും ബഹുമാനിക്കുകയും ചെയ്തിരുന്നു. നബി(സ)യുടെ ഓരോ പ്രവർത്തനവും അനുകരിക്കാനും ജീവിതത്തിൽ പകർത്താനും അവർ വളരെയധികം ശ്രദ്ധിച്ചു. പലരും അവിടുത്തോടൊപ്പം മസ്ജിദുന്നബവിയിൽ താമസമാക്കി. ചില സമയങ്ങളിൽ അവർ നൂറിലധികം പേരുണ്ടാകും. അഹ്ലുസ്സുഫ എന്ന പേരിലാണ് അവർ അറിയപ്പെട്ടത്. ചില സ്വഹാബികൾ (അനുയായികൾ) നബി(സ) എന്തു പറഞ്ഞു, എന്തു പ്രവർത്തിച്ചു എന്നറിയാൻ പരസ്പരം ഉത്തരവാദിത്തപ്പെടുത്തി ഊഴമിട്ട് നബി(സ)യുടെ കൂടെ ജീവിച്ചിരുന്നു. ഒരാൾ ജോലിക്കു പോകുമ്പോൾ മറ്റൊരാൾ നബി(സ)യുടെ കൂടെയുണ്ടാവും. അയാൾ ജോലിക്കു പോകുമ്പോൾ അയാളുടെ സ്നേഹിതനെ നബി(സ)യുടെ കൂടെ നിറുത്തും. ജോലിക്കു പോയ സ്നേഹിതൻ തിരിച്ചു വരുമ്പോൾ അദ്ദേഹത്തിന്റെ സ്നേഹിതൻ നബി(സ) അന്ന് പറഞ്ഞതും ചെയ്തതുമെല്ലാം സുഹൃത്തിനു പറഞ്ഞുകൊടുക്കും. ഒരു ഘട്ടത്തിൽ നബി(സ)യുടെ തലയിൽ എത്ര വെളുത്തമുടി ഉണ്ടായിരുന്നു എന്നുപോലും അവിടുത്തെ അനുയായികൾ ശ്രദ്ധിച്ചു മനസ്സിലാക്കിയിരുന്നു. ലോക ചരിത്രത്തിൽ ഇതുപോലെ സ്നേഹിക്കപ്പെട്ട, അനുകരിക്കപ്പെട്ട ഒരു ചരിത്ര പുരുഷൻ ഉണ്ടായിട്ടുണ്ടോ എന്ന് സംശയമാണ്.', null, '36' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'എന്തുകൊണ്ടാണ് ഹദീസുകൾ ഗ്രന്ഥരൂപത്തിലാക്കാൻ വൈകിയത് എന്ന് ചിലരെങ്കിലും സംശയിക്കും. ഉത്തരം വളരെ ലളിതമാണ്. ആദ്യകാലത്ത് നബി(സ)യുടെ സ്വഹാബിമാരും അവരെ പിന്തുടർന്നു', null, '36' from articles where volume_id=4 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'വന്നവരും ഹദീസുകൾ അനുസരിച്ചാണ് ജീവിച്ചുകൊണ്ടിരുന്നത്. അപ്പോൾ ഗ്രന്ഥരൂപത്തിൽ പ്രചരിപ്പിക്കേണ്ട ആവശ്യകത കുറവായിരുന്നു. എന്നാൽ ഇസ്ലാമിക സാമ്രാജ്യം വികസിക്കുകയും ഏഷ്യയിലേയും ആഫ്രിക്കയിലേയും വിവിധ ജനവിഭാഗങ്ങൾ ഇസ്ലാം സ്വീകരിക്കുകയും ചെയ്തപ്പോൾ ഈ അവസ്ഥ മാറി. അവരുടെ സമൂഹത്തിൽ സ്വഹാബിമാരുടെ എണ്ണം കുറഞ്ഞു. അതുകൊണ്ടാണ് ഗ്രന്ഥരൂപത്തിൽ എഴുതി ക്രോഡീകരിക്കേണ്ട ആവശ്യകത സമൂഹത്തിനു ബോദ്ധ്യപ്പെട്ടത്. പ്രവാചകർ(സ)യുടെ പ്രമുഖ സ്വഹാബികൾ റിപ്പോർട്ടു ചെയ്ത ഹദീസുകളുടെ എണ്ണം കുറയാനും ഈ അവസ്ഥ കാരണമായി. അവർ മദീനയിലാണ് ജീവിച്ചിരുന്നത്. അവരെല്ലാം നബി(സ) ജീവിച്ചുകാണിച്ചുതന്നത് അനുസരിച്ചാണ് ജീവിച്ചത്. അവർക്ക് നബി(സ)യുടെ ജീവിതത്തെപ്പറ്റി കൂടുതൽ അന്വേഷിക്കേണ്ടതിന്റെയും രേഖപ്പെടുത്തിവെക്കുന്നതിന്റെയും ആവശ്യകത അനുഭവപ്പെട്ടിരുന്നില്ല.', null, '37' from articles where volume_id=4 and section_no=3;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (4, 4, 'എന്താണ് ഹദീസ്', '37', '41');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'സ്വലാത്ത്, സകാത്ത് ഹജ്ജ് തുടങ്ങിയ പദങ്ങൾ ഉപയോഗിക്കുന്നതു പോലെ ഹദീസ് എന്നതും ഇസ്ലാമിലെ ഒരു സാങ്കേതിക പദമാണ്. വാക്കർത്ഥം ''പുതിയത്'' എന്നാണ്. എന്നാൽ ഇസ്ലാമിക ജീവിതത്തിൽ ഹദീസ് എന്നതുകൊണ്ട് ഉദ്ദേശിക്കപ്പെടുന്നത് നബി(സ) പറഞ്ഞതും ചെയ്തതുമായ കാര്യങ്ങളാണ്. നബി(സ)യുടെ സാന്നിധ്യത്തിൽ നടന്ന സംഭവങ്ങളും ഹദീസിൽ ഉൾപ്പെടുന്നു.', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'നബി(സ) പറഞ്ഞതും ചെയ്തതുമായ കാര്യങ്ങളിൽ മുസ്ലിം സമൂഹം അവിടുത്തെ കാലം മുതൽ താൽപര്യം കാണിച്ചു. അവ എഴുതി സൂക്ഷിക്കാനും താൽപര്യം കാണിച്ചിരുന്നു. അവർ അങ്ങനെ ചെയ്തതുകൊണ്ടാണ് പിൻതലമുറക്ക് ഹദീസുകൾ ലഭ്യമായത്.', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'ഹദീസുകൾ എഴുതി വെക്കുന്നതിൽ ഹദീസ് പണ്ഡിതന്മാർ വളരെ നിഷ്ക്കർഷത പുലർത്തി. പലരും വുളൂ എടുത്ത ശേഷമായിരുന്നു ഹദീസുകൾ എഴുതിവെച്ചിരുന്നത്. വളരെ ദൂരം സഞ്ചരിച്ചാണ് അവരിൽ പലരും ഹദീസുകൾ തേടിപ്പിടിച്ചത്. ഹദീസുകൾ തേടിപ്പിടിക്കുന്നതും അവയെക്കുറിച്ച് പഠിക്കുന്നതും അവ രേഖപ്പെടുത്തി വെക്കുന്നതും ജീവിതലക്ഷ്യമായി കണ്ടവരാണ് അവരിൽ പലരും.', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ഹദീസ് റിപ്പോർട്ടർമാരുടെ വിശ്വാസ്യത പരിശോധിക്കാൻ വേണ്ടി ആയിരക്കണക്കിനു റിപ്പോർട്ടർമാരുടെ ജീവചരിത്രം അവർ ശേഖരിച്ച് ഗ്രന്ഥരൂപത്തിലാക്കിയിട്ടുണ്ട്. അത്തരം കൃതികൾ അസ്മാഉർരിജാൽ എന്ന പേരിലാണറിയപ്പെടുന്നത്.', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'ഇത്രയധികം ഹദീസുകൾ പണ്ടുള്ളവർ എങ്ങനെ മനപ്പാഠമാക്കി മറ്റുള്ളവർക്ക് പകർന്നു കൊടുത്തു എന്നത് ആധുനികമനുഷ്യന് ഒരത്ഭുതമായിരിക്കും. ആധുനിക പഠനരീതികളും അതുമൂലം ഓർമ്മശക്തിക്കുണ്ടാകുന്ന കഴിവുകേടും നാം ശ്രദ്ധിക്കാറില്ല. നമ്മുടെ ഓർമ്മശക്തിയും അറേബ്യയിലെ ഗ്രാമീണരുടെ ഓർമ്മശക്തിയും തമ്മിൽ താരതമ്യപ്പെടുത്താവുന്നതല്ല. അവർ ഖണ്ഡകാവ്യങ്ങൾ മനപ്പാഠമാക്കിയിരുന്നു. അവരുടെ ഉപ്പ ഉപ്പൂപ്പമാരുടെ തലമുറകളുടെ ചരിത്രം അവർ ഓർമ്മിച്ചിരുന്നു. നബി(സ)യുടെ ഇരുപത് ഉപ്പൂപ്പമാരുടെ ചരിത്ര വിവരണം നമുക്ക് ലഭിച്ചത് അപ്രകാരമാണ്. ഇന്ന് നമുക്ക് കൂടുതൽ കാര്യങ്ങൾ ഓർമ്മിക്കാൻ കഴിയുന്നില്ല എന്നുള്ളതുകൊണ്ട് മുമ്പുള്ളവരും അങ്ങനെയായിരുന്നു എന്ന് ധരിക്കുന്നത് വിഡ്ഢിത്തമാണ്.', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ആധുനിക സമൂഹത്തിനു മതം ഒരു രണ്ടാംകിട ഏർപ്പാടാണ്. എന്നാൽ നബി(സ)യുടെ കാലഘട്ടത്തിലും, അതിനു തൊട്ടുപിന്നാലെവന്ന കാലഘട്ടത്തിലും ജനങ്ങൾക്ക് മതത്തോടുള്ള സമീപനം അങ്ങനെയായിരുന്നില്ല. മതം അവരെ സംബന്ധിച്ചിടത്തോളം ഏറ്റവും പ്രധാനപ്പെട്ട കാര്യമായിരുന്നു. അതുകൊണ്ടുതന്നെ അവർ നബി(സ) പറഞ്ഞതും ചെയ്തതുമായ കാര്യങ്ങൾ സൂക്ഷ്മമായി നിരീക്ഷിക്കുകയും അവ മനഃപ്പാഠമാക്കുകയും അവരുടെ ജീവിതത്തിൽ പകർത്തുകയും പിൻതലമുറകൾക്ക് കൈമാറുകയും ചെയ്തു. നമ്മുടെ ഇന്നത്തെ സ്വഭാവവും രീതിയും വെച്ച് നമുക്ക് അതു മനസ്സിലാക്കാൻ കഴിയില്ല. അതുകൊണ്ട് ലാഘവത്തോടെ ഹദീസുകളെ തള്ളിപ്പറയുന്നത് സൂക്ഷിക്കേണ്ടതുണ്ട്. അല്ലാഹു ഖുർആനിൽ', null, '37' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'നബി(സ)യെ അനുസരിക്കണമെന്നും അദ്ദേഹത്തിൽ ഉത്തമമായ മാതൃകയുണ്ടെന്നും പറയുമ്പോൾ, ഹദീസുകൾ വേണ്ട, ഖുർആൻ മാത്രം മതി എന്ന സമീപനം എങ്ങനെ ശരിയാവും?', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'നബി(സ)യുടെ കാലത്തിനു ശേഷം ഒന്നാം നൂറ്റാണ്ടിലോ രണ്ടാം നൂറ്റാണ്ടിലോ, സമൂഹത്തിൽ നബിചര്യയിൽ നിന്ന് വ്യത്യസ്തമായ കാര്യങ്ങൾ കൊണ്ടുവരാൻ കഴിയുമായിരുന്നില്ല. നബിചര്യ വളരെ കൃത്യമായി അനുധാവനം ചെയ്തിരുന്ന ഒരു സമൂഹത്തിൽ പുതുതായി എന്തെങ്കിലും കൊണ്ടുവന്നാൽ സമൂഹം മുഴുവൻ അതിനെ എതിർക്കുമായിരുന്നു. അത്തരമൊരു സാഹചര്യത്തിൽ നബി(സ) പഠിപ്പിച്ച ജീവിതശൈലിയിലും രീതിയിലും മാറ്റങ്ങൾ വരുത്തുക പ്രയാസമായിരുന്നു. അതുകൊണ്ട് നബിചര്യ അതേപോലെ നിലനിന്നു. ഈ വസ്തുതയും ആധുനികസമൂഹത്തിന് വേണ്ടത്ര ഉൾകൊള്ളാൻ കഴിയണമെന്നില്ല.', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ഹദീസ് നിഷേധം വളരെ അപകടകരമായ ഒരു പ്രവണതയാണ്. ഹദീസുകൾ നബിചര്യയെ പ്രതിനിധീകരിക്കുന്നില്ല എന്ന വിശ്വാസം പ്രചരിച്ചാൽ ഇസ്ലാമിന്റെ രണ്ട് അടിസ്ഥാനങ്ങളിൽ (ഖുർആനും നബിചര്യയും) ഒന്ന് ഇല്ലാതാവുകയാണ്. അതോടുകൂടി മുസ്ലിം സമുഹത്തിന്റെ രുപവും ഭാവവും കെട്ടുറപ്പും തകരും. മുസ്ലിം സമൂഹം ശിഥിലമാവും. അതാണ് ഓറിയന്റലിസ്റ്റുകളുടെ ലക്ഷ്യവും ആവശ്യവും. പാശ്ചാത്യ പണ്ഡിതന്മാർ ഖുർആനും ഹദീസും ഇസ്ലാമികചരിത്രവും പഠിച്ച് പുസ്തകങ്ങളെഴുതുന്നത് കുരിശുയുദ്ധത്തിന്റെ ഭാഗമായാണ്. ഇസ്ലാമിനെ എങ്ങനെ തകർക്കാം എന്നതാണവരുടെ ഗവേഷണവിഷയം. അതിനവർ കണ്ടെത്തിയ ഒരു മാർഗ്ഗമാണ് ഹദീസ് നിഷേധം. ഖുർആനിനെക്കുറിച്ചും ഹദീസുകളെക്കുറിച്ചും ഇസ്ലാമികചരിത്രത്തെക്കുറിച്ചും വേണ്ടത്ര പരിജ്ഞാനമില്ലാത്ത മുസ്ലിം ചെറുപ്പക്കാർ പാശ്ചാത്യരുടെ ഇത്തരം കൃതികൾ വായിച്ച് അതിൽ ആകൃഷ്ടരാവുന്നു. അവർക്കെന്തോ പുതിയ അറിവു ലഭിച്ചതുപോലെ അവരത് പ്രചരിപ്പിക്കാൻ ശ്രമിക്കുന്നു. അവർക്ക് കിട്ടിയ അറിവിന്റെ യഥാർത്ഥ അവസ്ഥയെക്കുറിച്ചോ അതിന്റെ അനന്തരഫലത്തെക്കുറിച്ചോ അവർ ചിന്തിക്കുന്നില്ല. അവർ അറിയാതെ ഓറിയന്റലിസ്റ്റുകളുടെ പണിയാളുകളാകുകയാണ്. ഓറിയന്റലിസ്റ്റുകളുടെ പുസ്തകങ്ങൾ അറബി ഭാഷയിലും അവർ പ്രസിദ്ധീകരിക്കുന്നു. അവ അറബ് നാടുകളിലെ സർവ്വകലാശാലകളിലെ ലൈബ്രറികളിലെത്തിക്കുന്നു. അറബ് യുവാക്കൾ അവ വായിച്ച് അതിന്റെ പ്രചാരകരാവുന്നു. അവർ അത്തരം പുസ്തകങ്ങൾ അവരുടെ യൂണിവേഴ്സിറ്റികളിലെ സിലബസുകളിലുൾപ്പെടുത്തുന്നു.', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'ഹദീസുകളുടെ ആധികാരികത സംശയിക്കുന്നതോടുകൂടി ഹദീസുകളും സുന്നത്തുകളും അനുസരിക്കപ്പെടേണ്ടവയല്ല എന്നൊരു ധാരണ യുവാക്കളുടെ മനസ്സുകളിൽ ഉണ്ടായി വരുന്നു. അതോടുകൂടി മതകർമ്മങ്ങളും സുന്നത്തുകളും പാലിക്കാത്ത അവസ്ഥ വരുന്നു. ഇസ്ലാമിക ചിഹ്നങ്ങൾ അപ്രത്യക്ഷമാവുന്നു. യുവാക്കൾ മറ്റു സംസ്ക്കാരങ്ങളുടെ പിന്നാലെ പോവുകയും അവയുടെ ഭാഗമായി മാറുകയും ചെയ്യുന്നു. മുസ്ലിം സമൂഹത്തിന്റെ വ്യതിരിക്തതയും അസ്തിത്വവും മെല്ലെ മെല്ലെ ഇല്ലാതെയാവുന്നു. ഹദീസ് നിഷേധത്തിൽ പതിയിരിക്കുന്ന ഈ അപകടം പലരും ശ്രദ്ധിക്കുന്നില്ല.', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'ഹദീസുകളുടെ ആധികാരികത സംശയിക്കപ്പെടുന്നതോടെ ഹദീസുകൾ നബിവചനങ്ങളല്ല എന്ന ധാരണയുണ്ടാവുന്നു. പെരുമാറ്റങ്ങളെക്കുറിച്ചും വേഷവിധാനങ്ങളെക്കുറിച്ചും ആചാരങ്ങളെക്കുറിച്ചുമെല്ലാം ഉള്ള ഹദീസുകൾ ഒഴിവാക്കിക്കഴിഞ്ഞാൽ പിന്നെ എന്താണവശേഷിക്കുക? ഹദീസുകളുടെ അഭാവത്തിൽ ഖുർആൻ വാക്യങ്ങളുടെ അർത്ഥമോ വ്യാഖ്യാനമോ മനസ്സിലാക്കാൻ സാധിക്കില്ല. അതോടുകൂടി ഖുർആൻ തന്നെ വളരെ ചുരുങ്ങിപ്പോവും. ഹദീസുകളുടെ അഭാവത്തിൽ ഖുർആൻ തന്നെ വേണ്ടരീതിയിൽ നിലനിൽക്കാതാവും.', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'ഹദീസുകൾ നിഷേധിക്കുന്നതോടെ ഇസ്ലാമികജീവിതം തന്നെ പ്രയോഗവത്കരിക്കാൻകഴിയാതെയാവും. ഉദാഹരണമായി, ഖുർആൻ നമസ്കരിക്കാൻ കൽപ്പിക്കുന്നു. എന്നാൽ എങ്ങനെ നമസ്കരിക്കണമെന്ന് ഹദീസുകളിൽ നിന്നേ നമുക്ക് ലഭിക്കൂ. ഹദീസുകളുടെ അഭാവത്തിൽ നമസ്ക്കാരത്തിന്റെ രൂപം വ്യക്തമാവുകയില്ല. സക്കാത്തിന്റെയും നോമ്പിന്റെയും ഹജ്ജിന്റെയുമൊക്കെ സ്ഥിതി ഇതുതന്നെയാണ്. അവയുടെ രൂപങ്ങൾ, അവയെപ്പറ്റിയുള്ള നിയമങ്ങൾ എന്നിവ നമുക്ക് ഹദീസിൽ നിന്നേ ലഭിക്കുന്നുള്ളൂ. ഹദീസുകൾ അവഗണിക്കുന്നതോടെ ഈ കർമ്മാനുഷ്ഠാനങ്ങളെല്ലാം പ്രയോഗവത്കരിക്കാൻ കഴിയാതെ വരും. അപ്പോൾ ഖുർആൻ നിർദ്ദേശിച്ച അത്തരം കാര്യങ്ങൾ ജീവിതത്തിൽ ഇല്ലാതെയാവും.', null, '38' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'ഖുർആൻ ജനങ്ങൾക്ക് എത്തിച്ചു കൊടുക്കുക എന്നത് മാത്രമല്ല നബി(സ)യെ അല്ലാഹു ഏൽപിച്ച ജോലി. ഖുർആന്റെ അദ്ധ്യാപനങ്ങൾക്കനുസരിച്ച് ഒരു സമൂഹത്തെ വാർത്തെടുക്കുക, ഒരു ഭരണ സംവിധാനം ഏർപ്പെടുത്തുക, മതാനുഷ്ഠാനങ്ങൾ, ആരാധനാക്രമങ്ങൾ എന്നിവ പഠിപ്പിക്കുക തുടങ്ങിയ ജോലികൾ കൂടി അല്ലാഹു നബി(സ)യെ ഏൽപ്പിച്ചിരുന്നു. ഈ ജോലികൾ അവിടുന്ന് ചെയ്തത് അല്ലാഹുവിന്റെ നിർദ്ദേശപ്രകാരമാണോ അല്ലയോ എന്നതാണ് പ്രസക്തമായ ചോദ്യം. നബി(സ) ഈ ജോലികൾ നിർവഹിച്ചത് അല്ലാഹുവിന്റെ അഭീഷ്ടപ്രകാരമാണ്. അവയെല്ലാം മാതൃകയാക്കേണ്ടത് ഓരോ മുസ്ലിമിന്റെയും ബാധ്യതയാണ് എന്ന് വ്യക്തം. ''അല്ലാഹുവിന്റെ ദൂതനിൽ നിങ്ങൾക്ക് ഉത്തമമായ മാതൃകയുണ്ട്'' എന്ന് അല്ലാഹു നിർദ്ദേശിച്ചതിനാൽ നാം നബി(സ)യെ മാതൃകയാക്കുമ്പോൾ അല്ലാഹുവിനെ അനുസരിക്കുകയാണ് ചെയ്യുന്നത്.', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'ഖുർആൻ ഓതിക്കേൾപിക്കുന്നതോടെ നബി(സ)യുടെ ജോലി തീർന്നുവോ? നബി(സ) ചെയ്ത ബാക്കി പ്രവർത്തനങ്ങളെല്ലാം ഒരു സാധാരണ മനുഷ്യന്റേതു മാത്രമാണോ? ആ ഘട്ടങ്ങളിലെല്ലാം നബി(സ) അല്ലാഹുവിന്റെ നബിയല്ലാതാകുന്നുണ്ടോ? മറ്റു സന്ദർഭങ്ങളിലും നബി(സ) നബിയല്ലാതാകുന്നില്ലെങ്കിൽ അവിടുത്തെ സുന്നത്തിന് നിയമസാധുതയുണ്ട് എന്ന് അംഗീകരിക്കേണ്ടി വരും. ഏതാണ് സുന്നത്ത്, ഏതാണ് സുന്നത്തല്ലാത്തത് എന്ന ചർച്ച മറ്റൊരു വിഷയമാണ്. നബി(സ)യുടെ സുന്നത്തിന് നിയമസാധുതയുണ്ടോ? അതു നാം അനുസരിക്കേണ്ടതുണ്ടോ? എന്നതാണ് അടിസ്ഥാനപരമായ ചോദ്യം. ഹദീസുകൾ നിഷേധിക്കുന്നതോടെ ഖുർആനിനെത്തന്നെയാണ് നിഷേധിക്കുന്നത്. അല്ലാഹുവിനെ അനുസരിക്കുക, അല്ലാഹുവിന്റെ ദൂതനെ അനുസരിക്കുക എന്ന ഖുർആനിന്റെ കൽപ്പനയെയാണ് നിഷേധിക്കുന്നത്. അല്ലാഹു മറ്റൊരിടത്ത് പറയുന്നു: ''പറയുക, നിങ്ങൾ അല്ലാഹുവിനെ സ്നേഹിക്കുന്നുവെങ്കിൽ എന്നെ പിൻപറ്റുക. എന്നാൽ അല്ലാഹു നിങ്ങളെ സ്നേഹിക്കുന്നതാണ്.'' (ഖു. 3: 31)', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'നബി(സ)യുടെ കാലം മുതൽ നമസ്കാരം, നോമ്പ്, ഹജ്ജ് തുടങ്ങിയ മത കർമ്മങ്ങളും ഇസ്ലാമിക ജീവിത രീതിയും, ഇസ്ലാമിക ആശയങ്ങളും തുടർച്ചയായി നിലനിന്നിട്ടുണ്ട്. ലോകത്തിന്റെ വിവിധ ഭാഗങ്ങളിൽ ജീവിക്കുന്ന മുസ്ലിം സമൂഹത്തിന് ഈ അടിസ്ഥാന കാര്യങ്ങളിൽ ഒരേ രീതിയാണുള്ളത്. ഇത് കാണിക്കുന്നത് മുസ്ലിം സമൂഹത്തിൽ സുന്നത്തിനുള്ള പ്രാധാന്യവും സ്വാധീനവുമാണ്. ഖുർആനിന്റെ താൽപര്യമനുസരിച്ച് രൂപംകൊണ്ടതാണിത്. സാമാന്യബുദ്ധിയുള്ള ആർക്കും ഇത് നിഷേധിക്കാനാവില്ല.', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'നബി(സ)യുടെ സുന്നത്ത് ഒരൊറ്റ ഗ്രന്ഥത്തിൽ ലഭിക്കുന്നതല്ലല്ലോ എന്നു പറയുന്നവരുണ്ട്. ഇരുപത്തിമൂന്ന് വർഷത്തെ സംഭവബഹുലമായ തിരുമേനി(സ)യുടെ ജീവിതം ഒറ്റ ഗ്രന്ഥത്തിൽ ക്രോഡീകരിക്കുക സാധ്യമല്ലെന്ന് ഏവർക്കും മനസ്സിലാക്കാവുന്നതാണ്. നബി(സ)യുടെ പ്രസംഗങ്ങൾ, അധ്യാപനങ്ങൾ, കോടതിവിധികൾ, ഭരണ നിയമങ്ങൾ, വിവാഹം, കച്ചവടം, ചരിത്ര പരാമർശങ്ങൾ തുടങ്ങി വിപുലമായ മേഖലകളിൽ നബി(സ)യുടെ ഹദീസുകൾ വ്യാപിച്ചു കിടക്കുന്നു. അതുകൊണ്ടുതന്നെ അവയെല്ലാം ഒരൊറ്റ ഗ്രന്ഥത്തിൽ ക്രോഡീകരിക്കുക അസാധ്യമാണ്.', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'സുന്നത്തിന്റെ കാര്യത്തിൽ അഭിപ്രായവ്യത്യാസങ്ങൾ ഉണ്ടല്ലോ? അതുകൊണ്ട് മൊത്തം സുന്നത്തിനെ തന്നെ തള്ളിക്കളയാം എന്നാണ് ചിലരുടെ നിലപാട്. എന്നാൽ ഖുർആൻ വാക്യങ്ങളുടെ ആശയങ്ങളുടെ കാര്യത്തിലും ഇങ്ങനെ അഭിപ്രായവ്യത്യാസങ്ങളുണ്ട്. അതുകൊണ്ട് ഖുർആൻതന്നെ തള്ളിക്കളയണമെന്ന് ആരും പറയുകയില്ലല്ലോ?', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'paragraph', 'അല്ലാഹു മുഹമ്മദ് നബി(സ)യെ ന്യായാധിപൻ അഥവാ വിധികർത്താവ് എന്ന് വിശേഷിപ്പിക്കുന്നുണ്ട്. ഈ വിശേഷണം നബി(സ) സ്വയം സ്വീകരിച്ചതോ ജനങ്ങൾ അവിടുത്തേക്ക് നൽകിയതോ അല്ല. അല്ലാഹു തന്നെയാണ് തിരുമേനി(സ)യെ വിധികർത്താവായി നിയമിക്കുന്നത്. ''നിശ്ചയം നാം അങ്ങേക്ക് സത്യസമേതം ഗ്രന്ഥം ഇറക്കിത്തന്നിരിക്കുന്നു. അല്ലാഹു കാണിച്ചു തന്ന വെളിച്ചത്തിൽ അങ്ങ് ജനങ്ങൾക്കിടയിൽ വിധി നടപ്പാക്കുന്നതിന് വേണ്ടി.'' (ഖു. 4: 105)', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'paragraph', '''അല്ലാഹുവിന്റെ അനുമതിയോടുകൂടി അനുസരിക്കപ്പെടുവാനല്ലാതെ ഒരു പ്രവാചകനെയും നാം അയച്ചിട്ടില്ല.'' (ഖു. 4: 80) നബി(സ) ഭരണാധികാരിയായത് അല്ലാഹുവിന്റെ തീരുമാനപ്രകാരമായിരുന്നു. അതുകൊണ്ടുതന്നെ ഭരണാധികാരി എന്ന നിലക്കുള്ള അവിടുത്തെ പ്രവർത്തനങ്ങൾ അനുസരിക്കാനും', null, '39' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'paragraph', 'മാതൃകയാക്കാനും മുസ്ലിംകൾ ബാധ്യസ്ഥരുമായിരുന്നു. അതും പ്രവാചകത്വത്തിന്റെ ഭാഗമായിരുന്നു എന്ന കാര്യത്തിൽ സ്വഹാബികൾക്ക് സംശയമുണ്ടായിരുന്നില്ല. വെറും ഭരണാധികാരി എന്ന നിലക്കല്ല, പ്രവാചകൻ എന്ന നിലക്കാണ് അവർ തിരുമേനി(സ)യെ അനുസരിച്ചതും സഹായിച്ചതും. അതിലെല്ലാം മുസ്ലിംകൾക്ക് മാതൃകയുണ്ട്.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'paragraph', 'ഖുർആനിൽ അല്ലാഹുവിനെ അനുസരിക്കാനും നബി(സ)യെ അനുസരിക്കാനും . അല്ലാഹു പ്രത്യേകം പറയുന്നുണ്ട്. അതിനർത്ഥം ഖുർആനിലില്ലാത്ത കാര്യങ്ങൾ നബി(സ)യിലൂടെ ലഭിക്കുന്നു എന്നതു തന്നെയാണ്. ഖുർആൻ കൂടാതെതന്നെ നബി(സ)ക്ക് അല്ലാഹുവിൽനിന്ന് മാർഗനിർദ്ദേശങ്ങൾ ലഭിച്ചിരുന്നുവെന്ന് ഖുർആൻതന്നെ ഇവിടെ വ്യക്തമാക്കുന്നുണ്ട്. കഅ്ബ ഖിബ്‌ലയാക്കുന്നതിനു മുമ്പ് മസ്ജിദുൽ അഖ്സയായിരുന്നു ഖിബ്‌ല. മസ്ജിദുൽ അഖ്സ ഖിബ്‌ലയാക്കാൻ ഖുർആനിലെവിടെയും നിർദ്ദേശമില്ല. അപ്പോൾ നബി(സ) മസ്ജിദുൽ അഖ്സയിലേക്ക് തിരിഞ്ഞ് നമസ്കരിച്ചത് എന്തിന്റെ അടിസ്ഥാനത്തിലായിരുന്നു. ഖുർആനിലില്ലാത്ത നിർദ്ദേശങ്ങൾ നബി(സ)ക്ക് ലഭിച്ചിരുന്നു എന്നതിന്റെ ഒരു ഉദാഹരണമായി ഇതിനെ കാണാവുന്നതാണ്. വർഷങ്ങളോളം തിരുമേനി(സ) മസ്ജിദുൽ അഖ്സ ഖിബ്‌ലയാക്കി നമസ്കരിച്ചിട്ടുണ്ട്. അല്ലാഹുവിന്റെ നിർദ്ദേശമില്ലാതെ നബി(സ) അങ്ങനെ ചെയ്യുമോ? ഖുർആനിൽ പറയാത്ത കാര്യങ്ങളിലും നബി(സ)യെ പിൻപറ്റാൻ മുസ്ലിംകൾ ബാധ്യസ്ഥരാണെന്ന് ഈ സംഭവം തെളിയിക്കുന്നു.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 22, 'paragraph', 'പ്രവാചകന്മാർ മഅ്സൂമുകളാണ്. തെറ്റുകളിൽനിന്ന് പരിരക്ഷ ലഭിച്ചവരാണ്. അവർ ചെയ്യുന്നതെല്ലാം അല്ലാഹുവിന്റെ അറിവോടെയും അവന്റെ സംരക്ഷണത്തിലുമായിരിക്കും. അതുകൊണ്ടുതന്നെ അവരുടെ പ്രവർത്തനങ്ങളിൽ മുസ്ലിംകൾക്ക് മാതൃകയുണ്ടാവും. ഖുർആനിൽ പറഞ്ഞിട്ടില്ലാത്ത മുഹമ്മദ് നബി(സ)യുടെ പ്രവർത്തനങ്ങളും അല്ലാഹുവിന്റെ അഭീഷ്ട പ്രകാരമാണെന്നർത്ഥം.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 23, 'paragraph', 'അല്ലാഹു പറയുന്നു: നബി(സ)ക്ക് വഹ്‌യ് മാത്രമല്ല, ഹിക്മത്ത് കൂടി നൽകിയിരിക്കുന്നു. ''അല്ലാഹു അങ്ങേക്ക് ഗ്രന്ഥവും തത്വജ്ഞാനവും അവതരിപ്പിച്ചു തരികയും അങ്ങേക്ക് അജ്ഞാതമായിരുന്നത് പഠിപ്പിക്കുകയും ചെയ്തു.'' (ഖു. 4: 113) ഖുർആൻ വാക്യങ്ങൾ കൂടാതെ മറ്റു ചിലതുകൂടി നബി(സ)ക്ക് നൽകപ്പെട്ടിരുന്നുവെന്ന് വ്യക്തം. ജനങ്ങൾക്ക് മാർഗദർശനം നൽകുന്നതിന്റെ ഭാഗം തന്നെയായിരുന്നു അത്. ജനങ്ങളെ സംസ്കരിക്കുക എന്ന ജോലികൂടി അല്ലാഹു തിരുമേനി(സ)യെ ഏൽപ്പിച്ചിരുന്നു. ''അക്ഷരജ്ഞാനമില്ലാത്തവർക്കിടയിൽ, തന്റെ ദൃഷ്ടാന്തങ്ങൾ അവർക്ക് വായിച്ചു കേൾപിക്കുകയും അവരെ സംസ്കരിക്കുകയും അവർക്ക് വേദഗ്രന്ഥവും തത്വജ്ഞാനവും പഠിപ്പിക്കുകയും ചെയ്യാൻ അവരിൽ നിന്നുതന്നെയുള്ള ഒരു ദൂതനെ നിയോഗിച്ചവനാകുന്നു അവൻ. തീർച്ചയായും അവർ മുമ്പ് വ്യക്തമായ വഴികേടിലായിരുന്നു.'' (ഖു. 62: 2)', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 24, 'paragraph', 'ബദർ യുദ്ധത്തിന്റെ അവസാനം സമരാർജിത സ്വത്തുക്കൾ വിതരണം ചെയ്യുന്ന ഘട്ടത്തിലാണ് സൂറത്തുൽ അൻഫാൽ അവതീർണ്ണമായത്. യുദ്ധത്തെ മൊത്തത്തിൽ അതിൽ അവലോകനം ചെയ്തിരിക്കുന്നു. നബി(സ) യുദ്ധത്തിനുവേണ്ടി വീട്ടിൽനിന്ന് ഇറങ്ങിപ്പുറപ്പെടുന്നത് മുതൽക്കാണ് പ്രസ്തുത അവലോകനം ആരംഭിക്കുന്നത്. അതിനെ പരാമർശിച്ചുകൊണ്ട് അല്ലാഹു പറഞ്ഞു: ''രണ്ടിലൊരു സംഘം നിങ്ങൾക്കുള്ളതാണെന്ന് അല്ലാഹു നിങ്ങളോട് വാഗ്ദാനം ചെയ്തിരുന്നു. ദുർബലസംഘം നിങ്ങൾക്കുള്ളതാണെന്ന് നിങ്ങൾ മോഹിക്കുകയും ചെയ്തു. തന്റെ വചനങ്ങൾ വഴി സത്യത്തെ സാക്ഷാൽകരിക്കാനും സത്യനിഷേധികളുടെ വേരറുക്കാനും അല്ലാഹു ഉദ്ദേശിച്ചിരുന്നു.'' (ഖു. 8: 7) ഇങ്ങനെ അല്ലാഹു നേരത്തെ നിർദ്ദേശിച്ചതായി ഖുർആനിൽ വന്നിട്ടില്ല.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 25, 'paragraph', 'ഖുർആൻ കൂടാതെ നബി(സ)ക്ക് വേറെയും ദൈവിക വെളിപാടുകൾ ഉണ്ടായിരുന്നുവെന്ന് സൂചിപ്പിക്കാനാണ് ഈ സംഭവം ഉദ്ധരിച്ചത്.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 26, 'paragraph', 'ഖുർആൻ കൂടാതെ നബി(സ)ക്ക് വഹ്‌യ് ലഭിച്ചിരുന്നു എന്നതിന് മറ്റൊരു ഉദാഹരണം ഇതാണ്: നബി(സ) ഭാര്യമാരിൽ ഒരാളോട് ഒരു രഹസ്യം പറഞ്ഞു. അവർ അത് മറ്റുള്ളവരോട് പറഞ്ഞു. നബി(സ) അതിനെക്കുറിച്ച് ചോദ്യം ചെയ്തപ്പോൾ താങ്കൾ എങ്ങനെയാണ് അത് അറിഞ്ഞതെന്ന് ചോദിക്കപ്പെട്ടു. അല്ലാഹു എന്നെ അറിയിച്ചതാണ് എന്നാണ് നബി(സ) മറുപടി പറഞ്ഞത്. ഖുർആനിലില്ലാത്ത കാര്യങ്ങളും അല്ലാഹു നബി(സ)യെ അറിയിക്കാറുണ്ടായിരുന്നുവെന്ന് ഈ സംഭവം വ്യക്തമാക്കുന്നു.', null, '40' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 27, 'paragraph', 'നബി(സ)യുടെ ദത്തുപുത്രനായ സൈദ്(റ) മൊഴിചൊല്ലിയ വനിതയെ നബി(സ) വിവാഹം ചെയ്തതിനെ സംബന്ധിച്ച് പരാമർശിക്കവെ അല്ലാഹുവാണ് അവരെ നബി(സ)ക്ക് വിവാഹം ചെയ്തുകൊടുത്തത് എന്ന് പറഞ്ഞു. അങ്ങനെ വിവാഹം ചെയ്തുകൊടുത്തതായി മുമ്പ് ഖുർആനിൽ പറഞ്ഞിട്ടില്ല.', null, '41' from articles where volume_id=4 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 28, 'paragraph', 'നിരന്തരം കുഴപ്പമുണ്ടാക്കിയിരുന്ന ബനുന്നദീർ ഗോത്രത്തെ നബി(സ)യുടെ സൈന്യം ഉപരോധിച്ചു. അതിനിടെ ചില മരങ്ങൾ മുറിച്ചു. മുസ്ലിം സൈന്യം മരങ്ങൾ മുറിച്ചതിനെ സംബന്ധിച്ച് ആക്ഷേപമുയർന്നപ്പോൾ ഖുർആനിൽ അല്ലാഹു പറഞ്ഞു: ''നിങ്ങൾ ഈത്തപ്പനകൾ മുറിക്കുകയോ അവ വേരുകളിൽ തന്നെ നിൽക്കാൻ വിടുകയോ ചെയ്തിട്ടുണ്ടെങ്കിൽ അത് അല്ലാഹുവിന്റെ അനുമതി പ്രകാരമാണ്.'' (ഖു. 59:, 5) ഇങ്ങനെ ഒരു നിർദ്ദേശം ഖുർആനിൽ മുമ്പ് വന്നതായി കാണുന്നില്ല. ഖുർആനിൽ വരാത്ത നിർദ്ദേശങ്ങളും നബി(സ)ക്ക് ലഭിച്ചിരുന്നുവെന്ന് ഇത് കാണിക്കുന്നു.', null, '41' from articles where volume_id=4 and section_no=4;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (4, 5, 'ഹദീസ് ശേഖരണം', '41', '42');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'വിവിധ മുസ്ലിം ഭരണാധികാരികൾക്ക് നബി(സ) അയച്ച മാർഗ്ഗനിർദ്ദേശങ്ങളുടെ രൂപത്തിലും സ്വഹാബിമാർ ഹദീസുകൾ പരസ്പരം എഴുത്തുരൂപത്തിൽ കൈമാറിയ രൂപത്തിലും, നബി(സ) മറ്റു ഭരണാധികാരികൾക്ക് ഇസ്ലാമിലേക്ക് ക്ഷണിച്ചുകൊണ്ടെഴുതിയ കത്തുകളുടെ രൂപത്തിലും, നബി(സ) പറഞ്ഞതും ചെയ്തതുമായ കാര്യങ്ങൾ വളരെയധികം സൂക്ഷ്മതയോടെ ഓർമ്മിച്ചിരുന്ന സ്വഹാബിമാരുടെ ഓർമ്മകളുടെ രൂപത്തിലും ഹദീസുകൾ നിലനിന്നു.', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'നബി(സ)യുടെ സ്വഹാബിമാരിൽ പലരും നബി(സ)യിൽ നിന്ന് കേട്ട ഹദീസുകൾ എഴുതിവെക്കാറുണ്ടായിരുന്നു. ഉദാഹരണമായി അംറുബ്നുൽ ആസ്¹, അബൂശിഹാബ്, സിയാദ് എന്നിവർ നബി(സ)യിൽ നിന്ന് കേട്ട ഹദീസുകൾ എഴുതിവെച്ചിരുന്നു.²', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'ഉമറുബ്നുൽഖത്താബ് (റ) മദീനയിൽ നിന്നും കുറച്ച് ദൂരെയാണ് താമസിച്ചിരുന്നത്. അതുകൊണ്ട് അദ്ദേഹത്തിന് എല്ലാ ദിവസവും നബി(സ)യോടൊപ്പം കഴിയാൻ സാധിക്കുമായിരുന്നില്ല. അതുകൊണ്ട് അദ്ദേഹം വരാത്ത ദിവസങ്ങളിൽ നബി(സ)യോടൊപ്പം കഴിയാൻ ഒരു അൻസാരി സുഹൃത്തിനെ ഏർപ്പാട് ചെയ്തിരുന്നു. ആ അൻസാരി സുഹൃത്ത് ഉമറുബ്നുൽഖത്താബ്(റ) വരാത്ത ദിവസങ്ങളിൽ നബി(സ) പറഞ്ഞ കാര്യങ്ങൾ ഉമർ(റ)വിനെ അറിയിക്കാറുണ്ടായിരുന്നു (ബുഖാരി). ഉമർ(റ) മാത്രം ചെയ്തിരുന്ന ഒരു രീതിയായിരുന്നില്ല ഇത്. മറ്റു പല സ്വഹാബിമാരും ഇങ്ങനെ ചെയ്യാറുണ്ടായിരുന്നു.³', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ഇസ്ലാമിക ഭരണം സിറിയ, ഈജിപ്ത്, ആഫ്രിക്ക, സെൻട്രൽ ഏഷ്യ, പേർഷ്യ തുടങ്ങിയ രാജ്യങ്ങളിലേക്ക് വ്യാപിച്ചപ്പോൾ പല സ്വഹാബിമാരും ആ പ്രദേശങ്ങളിലേക്ക് പോയി. അവർ അങ്ങനെ പോയപ്പോൾ അവരുടെ കൂടെ ഹദീസുകളും വ്യാപിച്ചു. ഹദീസ് ശേഖരിച്ചിരുന്നവർ പല രാജ്യങ്ങളിൽ നിന്നാണ് അവ ശേഖരിച്ചത്.', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'ഉമറുബ്നു അബ്ദുൽഅസീസ്(രണ്ടാം ഉമർ) ഖലീഫയായപ്പോൾ ഹദീസുകൾ ശേഖരിച്ചു. അദ്ദേഹം ഹിജാസിലെ ഗവർണ്ണറോട് ആഴ്ച്ചതോറും ഹദീസുകൾ ശേഖരിക്കാനും അവയെക്കുറിച്ച് ക്ലാസെടുക്കാനും നിർദ്ദേശിച്ചു. ആ ക്ലാസുകളിൽ പഠിച്ചവരെ ലോകത്തിന്റെ വിവിധപ്രദേശങ്ങളിലേക്ക് അയക്കാനും നിർദ്ദേശിച്ചു.⁴', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഉമറുബ്നു അബ്ദുൽഅസീസ് (രണ്ടാം ഉമർ) ഹദീസുകൾ ശേഖരിക്കാനും അവ ഗ്രന്ഥരൂപത്തിലാക്കാനും സഅദ്ബിൻ ഇബ്രാഹീം, ഇബ്നുശിഹാബ് അൽസുഹ്‌രി എന്നിവരെ നിയോഗിച്ചിരുന്നു.⁵ അബൂഖി', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'footnote', '¹. Ibn sa''d, vol 2, part 2, Kitab al Tabaqat al kabir, page 125 (Lieden 1904-18) Edward sachau', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'footnote', '². Hadith and Sunnah ideals and realities, Editor P.K Koya, Islamic book trust, Kuallampur, 2003, P7', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'footnote', '³. Hadith and Sunnah ideals and realities, Editor P.K Koya, Islamic book trust, Kuallampur 2003 P8', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'footnote', '⁴. Abdurahman bin al jawzi, Sirat Umar bin Abdul Aziz, (Egypit, 1331 A.H)', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'footnote', '⁵. Ibn sa''d, vol 1, part 1, Kitab al Tabaqat al kabir, page 45', null, '41' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'ലാബ (Qalabah) (d: 104 or 107 AH) ഹദീസുകൾ ശേഖരിച്ച് അവ ഗ്രന്ഥരൂപത്തിലാക്കുകയും അതിനെക്കുറിച്ച് ഒരു വസിയ്യത്ത് എഴുതിവെക്കുകയും ചെയ്തിരുന്നു.⁶', null, '42' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'മഖൂൽ (Makhul) മദീന, ഈജിപ്ത്, സിറിയ എന്നീ സ്ഥലങ്ങൾ സന്ദർശിച്ച് ഹദീസുകൾ ശേഖരിക്കുകയും അവ ഗ്രന്ഥരൂപത്തിലാക്കുകയും ചെയ്തതായി ഇബ്നുഹദീൽ അദ്ദേഹത്തിന്റെ ഫിഹിരിസ്ത് എന്ന ഗ്രന്ഥത്തിൽ പറയുന്നുണ്ട്.', null, '42' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'ഇബ്നുസഅദ് ധാരാളം ഹദീസുകൾ ശേഖരിച്ചിരുന്നതായും അദ്ദേഹത്തിന്റെ മരണശേഷം അതു നീക്കം ചെയ്യൽ ഒരു വലിയ ഭാരമായി അനുഭവപ്പെട്ടതായും ഇബ്നുസുഹ്‌രി പറയുന്നുണ്ട്.', null, '42' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'ആദ്യകാല പണ്ഡിതന്മാരുടെ പ്രവർത്തനങ്ങളുടെ ചുവടുപിടിച്ച് പല പണ്ഡിതന്മാരും ഇസ്ലാമിക ലോകത്തിന്റെ വിവിധ ഭാഗങ്ങളിൽ ഹദീസ് ശേഖരണവും ഗ്രന്ഥരചനകളും നടത്തിക്കൊണ്ടിരുന്നു. ഉദാഹരണമായി മദീനയിൽ മുഹമ്മദ് അബ്ദുറഹ്മാൻ, (d: 159 A.H) മക്കയിൽ അബ്ദുൽമാലിക്ക്ബ്നു അബ്ദുൽ അസീസ് ബിൻ ജുറൈജ്, (150 A.H / 760 A.D) മെസപ്പൊട്ടോമിയയിൽ സഅദ് ബിൻഅറൂബ (d: 157 A.H) സിറിയയിൽ അൽ അവ്സാഹി (d: 159 A.H) സൈദ്ബിൻ ഖുദാമ, (d: 160 A.H) സുഫ്‌യാനുസ്സൗരി(റ) (d: 160 A.H) എന്നിവർ കൂഫയിലും ഹമ്മാദ് ബിൻസലമ ബസറയിലും (d: 165 A.H) ഹദീസുകൾ ശേഖരിച്ച് ഗ്രന്ഥങ്ങൾ രചിച്ചു.⁷', null, '42' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'footnote', '⁶. Al-dahabi, Tadkirat al huffaz (hyderabad 1330 A.H) vol: 1, p 82', null, '42' from articles where volume_id=4 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'footnote', '⁷. Al-dahabi, Tadkirat al huffaz (hyderabad 1330 A.H) vol: 1, p 82', null, '42' from articles where volume_id=4 and section_no=5;
